<script>import {createEventDispatcher} from 'svelte';export let workflows=[];const dispatch=createEventDispatcher();</script>
<section><header><h2>Workflows</h2></header>{#if !workflows.length}<p>No workflows found.</p>{:else}<ul>{#each workflows as workflow (workflow.id || `${workflow.name}:${workflow.version}`)}<li><button on:click={()=>dispatch('select',workflow)}><strong>{workflow.name}</strong><small>Version {workflow.version || '1'}</small><span>{workflow.executions?.length || 0} execution{workflow.executions?.length === 1 ? '' : 's'}</span></button></li>{/each}</ul>{/if}</section><style>header{display:flex;justify-content:space-between;align-items:center}ul{list-style:none;padding:0;max-height:70vh;overflow:auto}li+li{margin-top:7px}button{font:inherit;cursor:pointer;border:1px solid #d7dce3;border-radius:6px;background:#fff;padding:9px 11px}li button{display:grid;text-align:left;width:100%;gap:4px}small,span{color:#697586;font-size:.8rem}</style>
